('returns-words','shopping-returns','words','Zakupy i zwrot','Покупка и возврат','8 карточек · A2','Назови документы, дефект и желаемое решение',7,'🛍️','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}',68,true),('returns-grammar','shopping-returns','grammar','Tańszy czy najlepszy?','Сравниваем товары','5 заданий · A2','Используй степени сравнения и формы количества',9,'✏️','Tańszy, droższy, najlepszy','[["Сравнение","Частые формы: tani → tańszy, drogi → droższy, dobry → lepszy, zły → gorszy."],["С чем сравниваем","Используй niż + именительный или od + родительный: tańszy niż ten; tańszy od tego."],["Количество","После pół kilo, dwóch, trzech нужен родительный: jabłek, paragonów, koszulek."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}',69,true),('returns-review','shopping-returns','review','Składam reklamację','Обмен товара','7 карточек · A2','Повтори сравнения и фразы возврата',7,'🔄','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}',70,true),('returns-quiz','shopping-returns','quiz','Quiz: zakupy i zwrot','Проверка темы','8 вопросов · A2','Проверь лексику и грамматику покупок',6,'🎯','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}',71,true),('returns-reading-check','shopping-returns','quiz','Czy rozumiesz reklamację?','Понимание текста','5 вопросов · A2','Проверь детали возврата Наталии',5,'📖','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}',72,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
