('returns-paragon','paragon','чек','Czy ma pani paragon?',241,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-zwrot','zwrot','возврат','Chcę zrobić zwrot tego produktu.',242,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-reklamacja','reklamacja','претензия; рекламация','Złożyłem reklamację w sklepie.',243,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-wymiana','wymiana','обмен','Proszę o wymianę na inny rozmiar.',244,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-wada','wada','дефект','Buty mają małą wadę.',245,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-rozmiar','rozmiar','размер','Ten rozmiar jest za mały.',246,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-przymierzyc','przymierzyć','примерить','Czy mogę przymierzyć tę kurtkę?',247,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-kosztowac','kosztować','стоить','Ile kosztuje ten sweter?',248,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-tanszy','tańszy','дешевле','Ten model jest tańszy od tamtego.',249,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-drozszy','droższy','дороже','Skórzana torba jest droższa.',250,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-lepszy','lepszy','лучше','Drugi materiał jest lepszy.',251,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-gorszy','gorszy','хуже','Ten zamek jest gorszy niż poprzedni.',252,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-oddac','oddać','вернуть','Mogę oddać produkt w ciągu czternastu dni.',253,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-uszkodzony','uszkodzony','повреждённый','Dostałam uszkodzony kubek.',254,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('returns-potwierdzenie','potwierdzenie','подтверждение','Mam potwierdzenie płatności w telefonie.',255,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}') on conflict(id) do update set polish=excluded.polish,translation=excluded.translation,example=excluded.example,position=excluded.position,is_active=excluded.is_active,source_metadata=excluded.source_metadata;
delete from public.lesson_flashcards where lesson_id in ('returns-words','returns-review'); insert into public.lesson_flashcards(lesson_id,flashcard_id,position) values ('returns-words','returns-paragon',0),('returns-words','returns-zwrot',1),('returns-words','returns-reklamacja',2),('returns-words','returns-wymiana',3),('returns-words','returns-wada',4),('returns-words','returns-rozmiar',5),('returns-words','returns-przymierzyc',6),('returns-words','returns-kosztowac',7),('returns-review','returns-tanszy',0),('returns-review','returns-drozszy',1),('returns-review','returns-lepszy',2),('returns-review','returns-gorszy',3),('returns-review','returns-oddac',4),('returns-review','returns-uszkodzony',5),('returns-review','returns-potwierdzenie',6);
delete from public.questions where lesson_id in ('returns-grammar','returns-quiz','returns-reading-check'); insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('returns-grammar','Ten sweter jest ___ niż tamten.','["tańszy","tani od","najtańszy niż"]',0,'Сравнительная степень tani — tańszy; с niż: tańszy niż tamten.',0),('returns-grammar','Ta kurtka jest ___ od poprzedniej.','["droższa","droga niż","najdroższy"]',0,'Для женского рода: droższa od poprzedniej.',1),('returns-grammar','Poproszę pół kilo ___.','["jabłka","jabłek","jabłkami"]',1,'После единицы количества нужен родительный множественного: pół kilo jabłek.',2),('returns-grammar','Это лучший размер.','["To jest lepszy rozmiar.","To jest najlepszy rozmiar.","To jest bardziej dobry rozmiar."]',1,'Превосходная степень dobry — najlepszy.',3),('returns-grammar','Potrzebuję dwóch ___.','["paragony","paragonów","paragonami"]',1,'После dwóch употребляется родительный множественного: dwóch paragonów.',4),
('returns-quiz','Что означает reklamacja?','["примерочная","претензия на товар","скидка"]',1,'Reklamacja — официальное обращение из-за дефекта товара.',0),('returns-quiz','Ten model jest ___ od starego.','["lepszy","dobry niż","najlepiej"]',0,'Сравнительная степень dobry — lepszy.',1),('returns-quiz','Poproszę kilogram ___.','["pomidorów","pomidory","pomidorami"]',0,'Количество требует родительного множественного: kilogram pomidorów.',2),('returns-quiz','Как попросить обмен на другой размер?','["Proszę o wymianę na inny rozmiar.","Proszę kosztować paragon.","Oddam rozmiar wadą."]',0,'Proszę o wymianę na inny rozmiar — вежливая просьба об обмене.',3),('returns-quiz','Buty są za małe, chcę je ___.','["oddać","kosztować","przymierza paragon"]',0,'Oddać — вернуть товар.',4),('returns-quiz','Która torba jest ___?','["najtańsza","bardziej tania od","tani"]',0,'Превосходная степень tani — najtańsza.',5),('returns-quiz','Что подтверждает покупку?','["paragon lub potwierdzenie płatności","rozmiar i wada","przymierzalnia"]',0,'Чек или подтверждение платежа доказывают покупку.',6),('returns-quiz','Potrzebuję trzech ___.','["koszulki","koszulek","koszulkami"]',1,'После trzech: родительный множественного — koszulek.',7),
('returns-reading-check','Dlaczego Natalia wróciła do sklepu?','["Kurtka miała uszkodzony zamek","Chciała kupić buty","Zgubiła telefon"]',0,'У куртки оказался повреждён замок.',0),('returns-reading-check','Czego Natalia nie miała?','["Karty płatniczej","Papierowego paragonu","Kurtki"]',1,'Бумажный чек она потеряла.',1),('returns-reading-check','Jak potwierdziła zakup?','["Pokazała płatność w aplikacji bankowej","Zadzwoniła do producenta","Przyniosła pudełko"]',0,'Она показала банковское подтверждение оплаты.',2),('returns-reading-check','Co zaproponował sprzedawca?','["Tylko droższy produkt","Wymianę albo zwrot pieniędzy","Naprawę za miesiąc"]',1,'Продавец предложил обмен или возврат денег.',3),('returns-reading-check','Co wybrała Natalia?','["Większy rozmiar","Zwrot pieniędzy","Tańszy, sprawny model"]',2,'Она обменяла куртку на исправную более дешёвую модель.',4);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('reklamacja-natalii','shopping-returns','Reklamacja Natalii','Возврат повреждённой куртки без бумажного чека','A2',5,'🛍️','["Natalia kupiła zimową kurtkę podczas wyprzedaży. W domu zauważyła, że zamek jest uszkodzony. Następnego dnia wróciła do sklepu, ale nie mogła znaleźć papierowego paragonu. Miała za to potwierdzenie płatności w aplikacji bankowej.","Sprzedawca sprawdził datę i kwotę zakupu. Powiedział, że Natalia może złożyć reklamację i wybrać wymianę albo zwrot pieniędzy. Natalia przymierzyła drugi egzemplarz, lecz był za duży. Inny model pasował lepiej i był trochę tańszy.","Natalia wybrała tańszy model. Sprzedawca zwrócił jej różnicę ceny na kartę i wysłał nowe potwierdzenie e-mailem. Cała rozmowa trwała kilkanaście minut. Natalia była zadowolona, bo nie musiała wracać do sklepu jeszcze raz."]','{"wyprzedaży":{"lemma":"wyprzedaż","translation":"распродажа","part_of_speech":"существительное"},"zauważyła":{"lemma":"zauważyć","translation":"заметить","part_of_speech":"глагол"},"uszkodzony":{"lemma":"uszkodzony","translation":"повреждённый","part_of_speech":"прилагательное"},"kwotę":{"lemma":"kwota","translation":"сумма","part_of_speech":"существительное"},"złożyć":{"lemma":"złożyć","translation":"подать","part_of_speech":"глагол"},"wymianę":{"lemma":"wymiana","translation":"обмен","part_of_speech":"существительное"},"egzemplarz":{"lemma":"egzemplarz","translation":"экземпляр","part_of_speech":"существительное"},"pasował":{"lemma":"pasować","translation":"подходить","part_of_speech":"глагол"},"różnicę":{"lemma":"różnica","translation":"разница","part_of_speech":"существительное"},"zwrócił":{"lemma":"zwrócić","translation":"вернуть","part_of_speech":"глагол"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28","comprehension_lesson_id":"returns-reading-check"}',16,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
